function freshVillage(){return {built:Object.fromEntries(Object.keys(PROJECTS).map(k=>[k,false])),dishes:Object.fromEntries(Object.keys(RECIPES).map(k=>[k,0])),cooked:0,nurseryDay:0,restDay:0,fertilizer:0,feedDays:{}}}
function normalizeVillage(v){const d=freshVillage();return {...d,...v,built:{...d.built,...v?.built},dishes:{...d.dishes,...v?.dishes},feedDays:{...v?.feedDays}}}
function validVillage(v,day){return !!v&&v.built&&Object.keys(PROJECTS).every(k=>typeof v.built[k]==='boolean')&&v.dishes&&Object.keys(RECIPES).every(k=>int(v.dishes[k],0,999999))&&int(v.cooked,0,1e9)&&int(v.nurseryDay,0,day)&&int(v.restDay,0,day)&&int(v.fertilizer,0,999999)&&v.feedDays&&typeof v.feedDays==='object'&&!Array.isArray(v.feedDays)&&Object.entries(v.feedDays).every(([k,d])=>/^(\d|1\d|2[0-3])$/.test(k)&&int(d,1,day))}
function indoor(){return ['cottage','kitchen'].includes(state.region)}
function worldSize(){return indoor()?{width:1400,height:960}:WORLD}
function cropArtKey(k){return CROPS[k]?.sheet!==undefined?'newCrops':k==='sunflower'?'sunflower':null}
function interiorProps(){const base=[{type:'door',to:state.region==='cottage'?'home':'town',x:700,y:900,w:170,h:38,target:{x:700,y:870},label:'出门'}];
 const item=(type,frame,x,y,w,h,label)=>({type,interior:frame,x,y,w,h,label,hit:{x:x-w*.35,y:y-48,w:w*.7,h:46},target:{x,y:y+38}});
 if(state.region==='cottage')return [...base,item('bed',0,340,500,230,235,'睡到明天'),item('construction',1,1090,475,270,195,'建设工作台'),item('pantry',2,790,380,200,235,'看看储物柜'),item('dining',4,720,665,230,152,'坐下吃点东西'),{type:'dining',detail:3,x:1120,y:740,w:180,h:185,hit:{x:1070,y:687,w:100,h:52},target:{x:1120,y:780}}];
 return [...base,item('stove',3,1070,450,285,228,'开始料理'),item('dining',4,810,690,225,148,'用餐'),item('counter',5,390,400,300,203,'料理柜台'),item('pantry',2,180,590,155,200,'查看食材'),{type:'resident',who:'bear',actor:1,x:550,y:555,w:90,h:110,target:{x:550,y:585}}];
}
function constructionProps(){const a=[];for(const [key,p] of Object.entries(PROJECTS)){if(!state.village.built[key])continue;a.push({...p,type:p.type,project:key,construction:p.frame,hit:key==='lamps'?null:{x:p.x-p.w*.32,y:p.y-38,w:p.w*.64,h:35},target:{x:p.x,y:p.y+40}});if(key==='lamps')for(const [x,y] of [[1420,690],[835,1085]])a.push({...p,x,y,type:'lamp',construction:2,project:key,w:70,h:142})}return a}
function homeObjects(){return [...props,...constructionProps()]}
function expansionInteract(o){if(o.type==='lamp'){toast('庭院路灯会在傍晚自动点亮。');return true}if(o.type==='home'){goRegion('cottage');return true}if(o.type==='bakery'){goRegion('kitchen');return true}if(o.type==='door'){goRegion(o.to);return true}if(o.type==='bed'){panel('home');return true}const pages={construction:'construction',pantry:'bag',dining:'dining',stove:'recipes',counter:'counter',nursery:'nursery',compost:'compost',rest:'rest'};if(pages[o.type]){panel(pages[o.type]);return true}return false}
function canCook(){return state.region==='kitchen'&&Math.hypot(state.x-1070,state.y-488)<135}
function recipeUnlocked(r){return !r.advanced||state.village.cooked>=3||state.travel.events.bear}
function hasIngredients(r){return Object.entries(r.ingredients).every(([k,n])=>state.stock[k]>=n)}
function ingredientText(r){return Object.entries(r.ingredients).map(([k,n])=>`${CROPS[k].name} ${state.stock[k]}/${n}`).join(' · ')}
let cookingUntil=0;
function villageAction(action,key){const v=state.village;let message='';
 if(action==='build'){const p=PROJECTS[key];if(!p||v.built[key])return '这个设施已经建好啦。';if(state.coins<p.coins||state.travel.wood<p.wood)return '材料还不够。木材可以在树林收集，每两天重新长出。';state.coins-=p.coins;state.travel.wood-=p.wood;v.built[key]=true;message=p.name+'建好啦！已经摆在庭院里，可以走近使用。';if(!passable(state.x,state.y)){state.x=790;state.y=655}}
 else if(action==='cook'){const r=RECIPES[key];if(!r||!canCook())return '走到料理铺右侧的炉灶旁，再开始制作。';if(!recipeUnlocked(r))return r.friend?'听完米米的「本子最后一页」，就能学到这道独家食谱。':'完成三次料理，或者和米米成为朋友后解锁。';if(!hasIngredients(r))return '食材不够，先去农田收获一些吧。';const e=expense(4);if(e)return e;for(const [k,n] of Object.entries(r.ingredients))state.stock[k]-=n;v.dishes[key]++;v.cooked++;cookingUntil=performance.now()+18000;message='做好了'+r.name+'！可在餐桌吃掉，也能拿到柜台售卖。'}
 else if(action==='eat-dish'){const r=RECIPES[key];if(!r||!v.dishes[key])return '背包里还没有这道料理。';if(state.energy>=maxEnergy())return '现在体力充足，留着饿的时候再吃吧。';v.dishes[key]--;state.energy=Math.min(maxEnergy(),state.energy+r.energy);message='吃下'+r.name+'，恢复 '+r.energy+' 点体力。'}
 else if(action==='sell-dish'){const r=RECIPES[key];if(!r||!v.dishes[key]||state.region!=='kitchen')return '到料理铺柜台出售做好的料理。';v.dishes[key]--;state.coins+=r.price;state.earned+=r.price;message=r.name+'售出，获得 '+r.price+' 金币。'}
 else if(action==='nursery'){if(!v.built.greenhouse||!Object.hasOwn(CROPS,key))return '';if(v.nurseryDay===state.day)return '今天已经领取过啦，明天温室会育好新的苗。';v.nurseryDay=state.day;state.seeds[key]++;message='从温室领到一份'+CROPS[key].name+'种子。'}
 else if(action==='compost'){if(!v.built.compost||!Object.hasOwn(CROPS,key)||state.stock[key]<2)return '需要两份同种作物。';state.stock[key]-=2;v.fertilizer+=2;message='制成两份肥料。到田边选「施肥」，每块田每天可用一次。'}
 else if(action==='rest'){if(!v.built.bench&&!v.built.gazebo)return '';if(v.restDay===state.day)return '今天已经休息过啦，明天再来坐坐。';if(state.energy>=maxEnergy())return '精神满满的，暂时不用休息。';v.restDay=state.day;state.energy=Math.min(maxEnergy(),state.energy+25);state.minute=Math.min(1320,state.minute+30);message='听了一会儿风声，恢复了 25 点体力。'}
 hud();save();return message;
}
function villageButton(action,key,label,disabled=false){return `<button data-village="${action}" data-key="${key}" ${disabled?'disabled':''}>${label}</button>`}
function expansionPanel(type){let title='',body='';const v=state.village;
 if(type==='construction'){title='把家园慢慢建起来';body=`<p>金币 ${state.coins} · 木材 ${state.travel.wood}。设施建好后会出现在庭院；已有农田不会被覆盖。</p><div class="build-grid">`+Object.entries(PROJECTS).map(([k,p])=>`<article class="project-card">${assetPortrait('construction',CONSTRUCTIONFRAMES,p.frame,85)}<h3>${p.name}${v.built[k]?' ✓':''}</h3><p>${p.desc}</p><small>${p.coins} 金币 · ${p.wood} 木材</small>${villageButton('build',k,v.built[k]?'已完工':'建造',v.built[k]||state.coins<p.coins||state.travel.wood<p.wood)}</article>`).join('')+`</div><p class="small">温室在家园东北侧；堆肥箱在温室南面；凉亭在西南角，长椅在南边。木材在树林拾取，两天刷新一次。</p>`}
 else if(type==='recipes'){title='米米的灶台';body=assetPortrait('roomDetails',ROOMDETAILFRAMES,4,95)+`<p>在料理铺右侧灶台旁烹饪。每次消耗 4 体力，推进 20 分钟。已完成 ${v.cooked} 次料理。</p>`+Object.entries(RECIPES).map(([k,r])=>`<article class="recipe-card"><h3>${r.name}<span>+${r.energy} 体力</span></h3><p>${r.desc}</p><small>${ingredientText(r)}</small>${villageButton('cook',k,!recipeUnlocked(r)?(r.friend?'听米米讲本子最后一页':'做过 3 次料理后解锁'):`制作 · 售价 ${r.price}`,!recipeUnlocked(r)||!hasIngredients(r)||!canCook()||state.energy<4||state.minute>=1320)}</article>`).join('')}
 else if(type==='dining'||type==='counter'){title=type==='dining'?'坐下来，好好吃顿饭':'米米的料理柜台';body=`<p>${type==='dining'?'料理可以恢复体力。食材和成品都放在背包里。':'做好的料理能在这里出售，也可以买饭团带在身上。'}</p>`+Object.entries(RECIPES).map(([k,r])=>`<div class="row"><span>${r.name} ×${v.dishes[k]}<small>${type==='dining'?'恢复 '+r.energy+' 体力':'售价 '+r.price+' 金币'}</small></span>${villageButton(type==='dining'?'eat-dish':'sell-dish',k,type==='dining'?'享用':'卖一份',!v.dishes[k]||type==='dining'&&state.energy>=maxEnergy())}</div>`).join('')+(type==='counter'?actionButton('buy-meal','买饭团 · 10 金币',state.coins<10):actionButton('eat','吃饭团 · +30 体力',!state.meals||state.energy>=maxEnergy()))}
 else if(type==='nursery'){title='温室育苗';body='<p>玻璃屋里总是暖暖的。每天可以挑一份种子带走，四季都能种。</p>'+Object.entries(CROPS).map(([k,c])=>`<div class="row"><span>${c.name}</span>${villageButton('nursery',k,v.nurseryDay===state.day?'明天再来':'领取一份',v.nurseryDay===state.day)}</div>`).join('')}
 else if(type==='compost'){title='田边的堆肥箱';body=`<p>两份同种作物 → 两份肥料。现有肥料 ${v.fertilizer} 份。每块田每天施肥一次，生长进度增加一天。</p>`+Object.entries(CROPS).map(([k,c])=>`<div class="row"><span>${c.name} ×${state.stock[k]}</span>${villageButton('compost',k,'制作肥料',state.stock[k]<2)}</div>`).join('')}
 else if(type==='rest'){title='在庭院歇一歇';body='<p>坐下来听听风声。每天恢复 25 点体力，花费 30 分钟；长椅和凉亭共用这一次休息机会。</p>'+villageButton('rest','','休息一会',v.restDay===state.day||state.energy>=maxEnergy())}
 else return false;
 keys.clear();moving=false;$('modal').hidden=false;$('modal-title').textContent=title;$('modal-body').innerHTML=body;$('modal').dataset.panel=type;$('panel-message').textContent='';$('modal-close').focus();return true;
}
function assetPortrait(key,frames,i,height){if(!images[key]?.width)return '';const f=frames[i],z=height/f[3];return `<span class="asset-portrait" style="width:${f[2]*z}px;height:${height}px;background-image:url('${ASSETS[key]}');background-size:${images[key].width*z}px ${images[key].height*z}px;background-position:${-f[0]*z}px ${-f[1]*z}px"></span>`}

function interiorDecor(){return (state.region==='cottage'?[[1,170,650,145,170],[2,450,530,90,205],[5,970,400,68,87]]:[[1,1190,725,150,178],[2,660,415,80,178],[5,230,785,76,99]]).map(([detail,x,y,w,h])=>({type:'roomDecor',detail,x,y,w,h}))}

