const FRIEND_SCENES={
 rabbit1:{who:'rabbit',level:12,title:'写歪的种子牌',pages:[['兔兔','这块牌子我写了三次，还是歪。新种子要是没发芽，大家会不会觉得我连种子也卖不好？'],['噜噜','她把牌子藏进围裙，又忍不住拿出来看。原来那句“慢慢来”，她自己也得练习。']],choices:['我陪你等它发芽','歪一点更认得出是你写的'],answers:['兔兔把牌子插回土里：“那我们过两天一起看。”','她终于笑了：“那就不重写了。这块是我的字。”'],reward:'兔兔送你 2 份胡萝卜种子。'},
 rabbit2:{who:'rabbit',level:28,title:'给你留的那一包',pages:[['兔兔','进货时我多留了一包草莓种子。不是新款，是去年有人说很甜的那种。'],['噜噜','她记得我说过想让院子有点香味。原来随口讲过的小事，也会被人放进下一次计划里。']],choices:['今年一起尝第一颗','先种在你也看得到的地方'],answers:['“那可说好啦，酸的也要一起尝。”','“我送货时就绕过来看看。”'],reward:'获得 2 份草莓种子和 1 份肥料。'},
 bear1:{who:'bear',level:12,title:'没盛出来的那碗汤',pages:[['米米','今天这锅汤我试了四次。以前有人说太淡，后来我总忍不住再添一点盐。'],['噜噜','米米推来一只小碗，却没有先问好不好吃。她在等我认真尝一口。']],choices:['我尝得到玉米本来的甜','留一碗淡的，我想这样喝'],answers:['米米松开了握勺子的手：“那我就不再添了。”','“好。不是每一碗，都得做成同一个味道。”'],reward:'米米装好 1 份玉米暖汤给你。'},
 bear2:{who:'bear',level:28,title:'本子最后一页',pages:[['米米','这页橘香小饼是我自己改的，试过好多次。一直没放进菜单，怕大家不喜欢。'],['噜噜','本子的角卷起来了，有一道面粉留下的白印。我把它摊平，等她讲完最后一个步骤。']],choices:['我想认真学会，再请你尝','先烤一盘，我们一起吃'],answers:['“那我会认真等你的第一盘。”','“好，这次不用先决定卖不卖。”'],reward:'解锁米米的独家食谱「橘香小饼」，得到 1 份橘子和 1 份小麦。'},
 turtle1:{who:'turtle',level:12,title:'一截没舍得扔的木头',pages:[['阿龟','你看，这里有个浅浅的刻痕。以前有人坐这条长椅等我，等烦了就在木头上划一下。'],['噜噜','他带着那截旧木头走了很久。我没有把它归到拾来的材料里。']],choices:['留着刻痕，做个新的靠背','今天先坐一会儿，听你讲'],answers:['“旧东西也可以有下一段日子。”','阿龟把木头放在身边，慢慢说起从前的码头。'],reward:'阿龟给你 3 份能用的木材，旧木头由他自己收好。'},
 turtle2:{who:'turtle',level:28,title:'还没有寄出的信',pages:[['阿龟','信写了许久，开头总是“岛上一切照旧”。最近终于能换一句了。'],['噜噜','他念给我听：“新邻居搬来了，有人在种田，也有人又愿意约一顿饭。”'],['阿龟','等灯塔再亮起来，就带这封信去海边。没修好也不急，你已经让这里变了不少。']],choices:['灯亮时，我陪你去','先把最近的事写进去'],answers:['“好，路上我再讲讲收信的那个人。”','“那今天就从你那顿晚饭写起。”'],reward:'得到 3 枚贝壳；阿龟会在日常聊天时提起这封信。'}
};
Object.assign(RECIPES,{orangeBiscuit:{name:'橘香小饼',ingredients:{orange:1,wheat:1},energy:65,price:96,friend:'bear2',desc:'米米本子最后一页的配方：熟悉她之后，亲口学到。'}});
function recordLife(key,n=1){if(state.life&&Object.hasOwn(state.life.counts,key))state.life.counts[key]=Math.min(1e9,state.life.counts[key]+n)}
function chapterAvailable(){return state.life.chapter<7&&state.day>=state.life.startDay+state.life.chapter}
function chapterTasks(n=state.life.chapter){const l=state.life,c=l.counts;return [
 [['走进自己的小屋',c.home>0],['种下一颗种子',c.sown>0],['让一块田喝到水（雨水也算）',c.watered>0]],
 LIFE_PEOPLE.map(k=>['和'+RESIDENTS[k].name+'聊过天',l.met.includes(k)]),
 [['收集 3 份木材',c.wood>=3],['看看建设图纸',c.plans>0]],
 [['收获至少 2 份作物',c.harvested>=2],['送兔兔一颗胡萝卜',l.giftCarrot]],
 [['亲手做出一道料理',c.cooked>0]],
 [['建好一项庭院设施',Object.values(state.village.built).some(Boolean)]],
 [['带上一份料理',Object.values(state.village.dishes).some(n=>n>0)],['到家园或小屋等到 17:00', ['home','cottage'].includes(state.region)&&state.minute>=1020]]
 ][n]||[]}
function chapterReady(){return chapterAvailable()&&state.life.seen.includes(state.life.chapter)&&chapterTasks().every(t=>t[1])}
function chapterReward(n){const l=state.life;if(n===0)state.seeds.carrot+=2;if(n===1){state.seeds.wheat+=2;state.seeds.corn++}if(n===2){state.coins+=35;state.seeds[l.choices[2]==='gentle'?'berry':'cabbage']+=2}if(n===3){state.coins+=30;state.stock.wheat+=2}if(n===4){state.stock.corn++;state.stock.carrot++}if(n===5&&!Object.values(state.village.dishes).some(n=>n>0))state.village.dishes.bread++;if(n===6)LIFE_PEOPLE.forEach(k=>state.travel.relations[k]=Math.min(100,state.travel.relations[k]+8))}
function finishChapter(){if(!chapterReady())return '事情还没准备好，可以慢慢来。';const n=state.life.chapter;if(n===6)return '选一份料理，邀请大家开饭吧。';chapterReward(n);state.life.done.push(state.day);state.life.chapter++;save();hud();return LIFE_CHAPTERS[n].ending+' '+LIFE_CHAPTERS[n].reward}
function partyActive(){return state.life.partyDay===state.day&&state.life.chapter===7}
function startSupper(key){if(state.life.chapter!==6||!chapterReady()||!RECIPES[key]||!state.village.dishes[key])return '先带上一份料理，在家园或小屋等到傍晚。';state.village.dishes[key]--;state.life.partyDish=key;state.life.partyDay=state.day;state.life.partyPlace=state.rain?'cottage':'home';chapterReward(6);state.life.done.push(state.day);state.life.chapter=7;save();goRegion(state.life.partyPlace);if(state.region===state.life.partyPlace){state.x=state.region==='cottage'?700:1050;state.y=state.region==='cottage'?805:1460;save()}return '大家来了！'+(state.rain?'雨落在窗外，今晚在小屋里吃饭。':'院子里的桌子摆好了，大家带来了自己的拿手菜。')}

// A resident has exactly one location at any game time. The shop stays self-service.
function residentSchedule(who,minute=state.minute,rain=state.rain){let a;
 if(partyActive())a=state.life.partyPlace==='home'?{rabbit:['home',920,1350,'帮忙摆杯子'],bear:['home',1105,1325,'招呼大家吃饭'],turtle:['home',1180,1400,'慢慢喝热汤']}[who]:{rabbit:['cottage',585,690,'递来餐盘'],bear:['cottage',850,620,'给大家盛汤'],turtle:['cottage',870,770,'坐下聊旧事']}[who];
 else if(rain)a=who==='rabbit'?(minute<1080?['town',870,685,'在棚下整理种子']:['kitchen',580,745,'躲雨喝热茶']):who==='bear'?['kitchen',540,555,'看着慢炖的汤锅']:['kitchen',650,785,'听雨，整理旧信'];
 else if(who==='rabbit')a=minute<540?['home',1090,645,'查看菜苗']:minute<960?['town',870,685,'整理种子摊']:minute<1140?['forest',700,610,'收集落下的种子']:['kitchen',580,745,'吃晚饭'];
 else if(who==='bear')a=minute<540?['town',1060,840,'挑选今天的食材']:minute<1020?['kitchen',540,555,'在灶台边备菜']:minute<1140?['town',1090,500,'饭前散散步']:['kitchen',540,555,'收拾餐具'];
 else a=minute<600?['pond',900,560,'看看今天的水色']:minute<1020?(state.history.bridge?['coast',1110,600,'在灯塔边写信']:['forest',1000,760,'挑选能用的木料']):minute<1140?['pond',1100,940,'在水边歇脚']:['town',1020,860,'慢慢走过广场'];
 return {region:a[0],x:a[1],y:a[2],activity:a[3]};
}
function scheduledResidents(){return LIFE_PEOPLE.map((who,actor)=>{const s=residentSchedule(who);return {type:'resident',who,actor,...s,w:who==='rabbit'?83:90,h:105,target:{x:s.x,y:s.y+34}}}).filter(o=>o.region===state.region)}
function nearResident(who){const s=residentSchedule(who);return s.region===state.region&&Math.hypot(state.x-s.x,state.y-(s.y+34))<135}
function availableFriendScenes(who){return Object.entries(FRIEND_SCENES).filter(([k,s])=>s.who===who&&state.travel.relations[who]>=s.level&&!state.life.events.includes(k)&&(!k.endsWith('2')||state.life.events.includes(who+'1')))}
function residentGreeting(who){const s=residentSchedule(who),m=state.life.memories[who];if(partyActive())return {rabbit:'你的院子真适合坐下来。以后收摊，我能来这里歇一会儿吗？',bear:'你做的那份我尝过了。下一次换我请大家。',turtle:'以前写信总说岛上一切照旧。今天可以多写一页了。'}[who];if(m&&state.day>m.day&&state.day-m.day<=3)return `你上次送来的${m.type==='dish'?RECIPES[m.key].name:CROPS[m.key].name}，我还记得。`+{rabbit:'我特意留到收摊以后慢慢吃。',bear:'下次有空，一起坐下来尝尝。',turtle:'有心惦记人的礼物，总让路也近了一点。'}[who];if(who==='turtle'&&state.life.events.includes('turtle2'))return state.history.lighthouse?'灯亮了。那封信的最后一句，我终于写好了。':'我又在信里添了几句近来的事。灯塔的事，我们慢慢来。';if(state.rain)return {rabbit:'种子不能淋湿，我在棚子底下守着。你的田今天倒能少忙一点。',bear:'雨一落下来，就想把汤炖得久一点。进来暖暖手吧。',turtle:'今天不走远了。听雨的时候，旧事总想得慢一些。'}[who];const phase=state.minute<600?0:state.minute<1020?1:2;return {rabbit:['我来看看新苗。你不在时也没替你乱浇水，放心。','今天有人问哪种草莓甜。我想等我们自己尝过再推荐。','收摊以后才觉得饿了。晚饭总得好好吃。'],bear:['我在挑午饭用的菜，有点歪的也一样好吃。','汤还得等一会儿。我可以先教你看火，不用站着发愁。','忙完一阵，我喜欢出门闻闻和厨房不一样的气味。'],turtle:['水面没什么风。早一点来，总能看清小鱼往哪儿游。','这根木料还好，带回去修椅子正合适。','我走得慢。你有事就先去，不用为了陪我一直等。']}[who][phase]}
function friendReward(id,choice){if(state.life.events.includes(id))return;state.life.events.push(id);state.life.eventChoices[id]=choice;if(id==='rabbit1')state.seeds.carrot+=2;if(id==='rabbit2'){state.seeds.berry+=2;state.village.fertilizer++}if(id==='bear1')state.village.dishes.soup++;if(id==='bear2'){state.stock.orange++;state.stock.wheat++}if(id==='turtle1')state.travel.wood+=3;if(id==='turtle2')state.travel.shells+=3;save()}
function shareDish(who,key){if(!nearResident(who)||!RECIPES[key]||!state.village.dishes[key])return '走到这位邻居身边，再分享背包里的料理。';if(state.travel.giftDays[who]===state.day)return '今天已经送过礼物啦，留一份明天再分享。';const favorite={rabbit:'salad',bear:'bread',turtle:'soup'}[who]===key;state.village.dishes[key]--;state.travel.giftDays[who]=state.day;state.travel.relations[who]=Math.min(100,state.travel.relations[who]+(favorite?12:7));state.life.memories[who]={type:'dish',key,day:state.day};save();hud();return RESIDENTS[who].name+'：'+(favorite?'这是我很喜欢的味道！':'谢谢你特意给我留了一份。')+` 好感 +${favorite?12:7}。`}

