function migrateOld(old){if(valid(old))return JSON.parse(JSON.stringify(old));if(!old||![1,2].includes(old.version))throw Error('格式不支持');const s=fresh();if(old.version===2){if(!int(old.day,1,999999)||!int(old.coins,0,1e9)||!int(old.seeds,0,999999)||!int(old.carrots,0,999999)||!Array.isArray(old.plots)||old.plots.length!==6)throw Error('样板存档有误');for(const k of ['day','rain','minute','coins','energy','water','shipping','harvests','meals','introduced'])s[k]=old[k];s.seeds.carrot=old.seeds;s.stock.carrot=old.carrots;s.plots=old.plots.map(p=>{if(!p||typeof p.planted!=='boolean'||!int(p.growth,0,3)||typeof p.wet!=='boolean')throw Error('作物数据有误');return {crop:p.planted?'carrot':null,growth:p.planted?p.growth:0,wet:p.wet,repeat:false}})}else{if(!Array.isArray(old.items)||!Number.isFinite(old.x)||!Number.isFinite(old.y))throw Error('探险存档无效');const h=s.history;for(const k of ['cat','bridge','gift','lighthouse','party']){if(old[k]!==undefined&&typeof old[k]!=='boolean')throw Error('探险数据有误');h[k]=!!old[k]}h.fish=old.fish||[0,0,0,0];h.items=old.items||[];h.shells=old.shells||[];const f=old.farm;if(f){if(!int(f.day,1,999999)||!int(f.water,0,1)||!int(f.house,0,1)||!Array.isArray(f.plots)||![6,9,12].includes(f.plots.length)||!f.seeds||!f.bag)throw Error('农场存档有误');s.day=f.day;s.rain=f.weather==='rain';s.minute=f.minute;s.coins=f.coins;s.house=f.house?2:0;s.energy=Math.min(maxEnergy(s),f.energy);s.can=f.water?1:0;s.water=maxWater(s);s.shipping=f.shipping;s.harvests=f.harvests;s.earned=f.earned;s.meals=f.bag.meal;h.pet=f.pet||0;s.fishStock=[0,1,2,3].map(i=>f.bag['fish'+i]||0);for(const k of ['carrot','berry','orange']){s.seeds[k]=f.seeds[k];s.stock[k]=f.bag[k]}s.plots=f.plots.map(p=>{if(!p||p.crop!==null&&!['carrot','berry','orange'].includes(p.crop)||!int(p.growth,0,5)||typeof p.watered!=='boolean'||typeof p.repeat!=='boolean')throw Error('农田数据有误');if(!p.crop)return emptyPlot();const oldDays=p.repeat?{berry:2,orange:3}[p.crop]:{carrot:2,berry:3,orange:5}[p.crop];const n={crop:p.crop,growth:0,wet:p.watered,repeat:p.repeat};if(!oldDays)throw Error('生长数据有误');n.growth=Math.min(daysFor(n),Math.ceil(p.growth/oldDays*daysFor(n)));return n});while(s.plots.length<12&&s.plots.length>6)s.plots.push(emptyPlot())}}
s.x=790;s.y=655;s.introduced=true;s.life=normalizeLife(null,s.day,s);if(!valid(s))throw Error('存档字段不完整或无效');return s}
