const RESIDENTS={rabbit:{name:'兔兔',favorite:'carrot',line:'每天都有新种子，也总有值得期待的小事情。'},bear:{name:'米米',favorite:'berry',line:'煮一碗暖暖的汤，再去远一点的地方看看吧。'},turtle:{name:'阿龟',favorite:'pumpkin',line:'灯塔的光，会把出海的朋友平安带回来。'}};
