const images={},imageJobs={};let ready=false,travelTicket=0,loadingRegion=null;
function loadArt(key){if(images[key]?.width>0)return Promise.resolve(images[key]);if(imageJobs[key])return imageJobs[key];imageJobs[key]=new Promise((resolve,reject)=>{const im=new Image();im.decoding='async';im.onload=async()=>{try{if(im.decode)await im.decode();images[key]=im;resolve(im)}catch(e){delete imageJobs[key];reject(e)}};im.onerror=()=>{delete imageJobs[key];reject(Error('图片加载失败'))};im.src=ASSETS[key]});return imageJobs[key]}
function regionArt(region){return region==='home'?'ground':region}
function regionAssets(region){const crops=region==='home'?[...new Set(state.plots.filter(p=>p.crop).map(p=>cropArtKey(p.crop)).filter(Boolean))]:[];return [regionArt(region),...(region==='home'&&partyActive()?['furniture']:[]),...(['town','forest','pond'].includes(region)?['regionTrees']:[]),...(['cottage','kitchen'].includes(region)?['furniture','roomDetails']:[]),...crops]}
function loadingMessage(label,retry){const node=$('loading');node.hidden=false;node.textContent=label;if(retry){const b=document.createElement('button');b.textContent='重新加载';b.onclick=retry;node.appendChild(b)}}
function ensureRegionArt(){const keys=regionAssets(state.region);if(keys.every(k=>images[k]?.width>0))return true;const key=keys.join('+');if(loadingRegion===key)return false;loadingRegion=key;stopWalking();loadingMessage('正在打开'+REGION_NAMES[state.region]+'…');Promise.all(keys.map(loadArt)).then(()=>{loadingRegion=null;$('loading').hidden=true}).catch(()=>{loadingMessage('这张地图没能加载，请检查网络后重试。',()=>{loadingRegion=null;ensureRegionArt()})});return false}
function goRegion(name){if(!Object.hasOwn(REGION_NAMES,name)||!openRegion(name))return goRegionNow(name);const ticket=++travelTicket,required=regionAssets(name);if(required.every(k=>images[k]?.width>0))return goRegionNow(name);stopWalking();keys.clear();dismiss();loadingMessage('正在前往'+REGION_NAMES[name]+'…');Promise.all(required.map(loadArt)).then(()=>{if(ticket!==travelTicket)return;$('loading').hidden=true;goRegionNow(name)}).catch(()=>{if(ticket===travelTicket)loadingMessage('地图加载失败，进度已保留。',()=>goRegion(name))})}
