function atlas(frame,x,y,w,h,alpha=1){const f=ATLAS[frame],scale=Math.min(w/f[2],h/f[3]),dw=f[2]*scale,dh=f[3]*scale;ctx.save();ctx.globalAlpha=alpha;ctx.drawImage(images.atlas,...f,x-dw/2,y-dh,dw,dh);ctx.restore()}
