const idleLines={rabbit:['胡萝卜叶子也在点头呢。','今天的小镇真热闹呀。','好舒服的青草香呀。'],bear:['汤锅咕嘟咕嘟，快好了。','今晚做南瓜浓汤吧。','歇会儿再忙也不迟。'],turtle:['池塘的风有薄荷味。','我又想起那座灯塔。','今天适合慢慢散步。']};
function windDraw(x,y,t,amp,phase,draw,bob=0){ctx.save();ctx.translate(x,y);ctx.rotate(Math.sin(t*.00115+phase)*amp);ctx.translate(0,Math.sin(t*.00155+phase)*bob);draw();ctx.restore()}
function treeCanopy(o,t){const size=o.size||1,scale=Math.min(o.w*size/303,o.h*size/360),w=303*scale,h=360*scale,phase=o.x*.013+o.y*.009,flip=o.flip?-1:1;ctx.save();ctx.translate(o.x,o.y);ctx.scale(flip,1);ctx.drawImage(images.treeParts,0,0,303,360,-w/2,-h,w,h);ctx.restore();ctx.save();ctx.translate(o.x+Math.sin(t*.00082+phase)*4.5,o.y+Math.sin(t*.0011+phase+1.2)*1.1);ctx.rotate(Math.sin(t*.00072+phase)*.014);ctx.scale(flip,1);ctx.drawImage(images.treeParts,303,0,303,360,-w/2,-h,w,h);ctx.restore()}
