function residentPose(o,t,paused=false){const profile={rabbit:{period:19,range:27},bear:{period:27,range:19},turtle:{period:34,range:16}}[o.who]||{period:24,range:18};const u=paused ? .68 : ((t/1000+o.actor*3.7+o.x*.001)%profile.period)/profile.period,ease=v=>{v=Math.max(0,Math.min(1,v));return v*v*(3-2*v)};let offset=0,walking=false,direction=1;if(u<.21){offset=-profile.range+2*profile.range*ease(u/.21);walking=true;direction=1}else if(u<.29){offset=profile.range;direction=1}else if(u<.5){offset=profile.range-2*profile.range*ease((u-.29)/.21);walking=true;direction=-1}else if(u<.58){offset=-profile.range;direction=-1}else if(u<.67){offset=-profile.range+profile.range*ease((u-.58)/.09);walking=true;direction=1}else if(u<.84){offset=0;direction=1}else{offset=-profile.range*ease((u-.84)/.16);walking=true;direction=-1}const beat=t*.012+o.actor*2.2,hop=!paused&&o.who==='rabbit'&&((u>.16&&u<.21)||(u>.62&&u<.67))?Math.sin(Math.PI*((u>.62?u-.62:u-.16)/.05))*5:0;return {offset,walking,bob:paused?0:(walking?Math.abs(Math.sin(beat))*2.3+hop:Math.sin(t*.002+o.actor)*.8),tilt:paused?0:(walking?Math.cos(beat)*.035:Math.sin(t*.0015+o.actor)*.012),flip:direction<0,talk:!paused&&u>.72&&u<.84,u}}
function residentIdle(o,t){const pose=residentPose(o,t,!$('modal').hidden),person={...o,x:o.x+pose.offset};shadow(person.x,o.y-2,o.w*.28,8,.13);ctx.save();ctx.translate(person.x,o.y+pose.bob);if(pose.flip)ctx.scale(-1,1);ctx.rotate(pose.tilt);extra(images.people,PEOPLEFRAMES,o.actor,0,0,o.w,o.h);ctx.restore();if(pose.talk){const fade=Math.min(1,(pose.u-.72)/.025,(.84-pose.u)/.035),lines=idleLines[o.who]||['今天的风真舒服。'];speechBubble(person,lines[Math.floor((t/12000+o.actor*1.3)%lines.length)],fade)}}
