let lifeScene=null;
function lifeButton(action,key,label,disabled=false){return `<button data-life="${action}" data-key="${key}" ${disabled?'disabled':''}>${label}</button>`}
function showLifePanel(type,title,body){stopWalking();keys.clear();$('modal').hidden=false;$('modal').dataset.panel=type;$('modal-title').textContent=title;$('modal-body').innerHTML=body;$('panel-message').textContent='';$('modal-close').textContent='回到小镇';$('modal-title').focus({preventScroll:true});$('modal-title').parentElement?.scrollTo(0,0)}
function lifePanel(type){
 if(type==='life'){const l=state.life,n=l.chapter,c=LIFE_CHAPTERS[n];let body=`<div class="life-heading"><span>第一周 · ${Math.min(n+1,7)} / 7</span><b>${n===7?'已经有了家的样子':'不必赶进度，便条不会过期'}</b></div>`;
 if(c){const wait=state.day<l.startDay+n;body+=`<article class="life-note"><small>第 ${n+1} 封便条${wait?' · 下一天送到':''}</small><h3>${c.title}</h3><p>${c.subtitle}</p>`;
 if(wait)body+='<p>今天先照顾田地、认识邻居，或者回小屋睡到明天。</p>';
 else if(!l.seen.includes(n))body+=lifeButton('chapter',String(n),'拆开今天的便条');
 else {body+='<ul class="life-tasks">'+chapterTasks().map(([label,ok])=>`<li class="${ok?'done':''}">${ok?'✓':'○'} ${label}</li>`).join('')+'</ul>';
 if(n===6){body+='<p>17:00 后可以开饭，晴天在庭院，下雨就在小屋。晚一点也没关系。</p>'+lifeButton('wait','evening','歇到 17:00',state.minute>=1020)+Object.entries(RECIPES).filter(([k])=>state.village.dishes[k]>0).map(([k,r])=>lifeButton('supper',k,'端上'+r.name+'，邀请大家',!chapterReady())).join('')}
 else body+=lifeButton('finish','','把这一天写进手记',!chapterReady());body+=lifeButton('chapter',String(n),'再读一遍便条');}
 body+=`<p class="small">${c.reward}</p></article>`}
 else body+='<article class="life-note"><h3>以后也一起吃饭吧</h3><p>七封便条都留在这里了。继续照顾家园，和朋友聊天、分享料理，还会读到他们各自的小故事。</p>'+lifeButton('album','','重看邻居晚饭')+'</article>';
 body+='<h3>已经留下的日子</h3>'+LIFE_CHAPTERS.map((p,i)=>`<div class="row"><span>${i+1}. ${p.title}<small>${i<n?'在第 '+l.done[i]+' 天完成':i===n?'正在经历':'后续便条'}</small></span>${i<n?lifeButton('chapter',String(i),'重读'):''}</div>`).join('');
 body+='<p class="small">旧存档从更新当天开始这段生活，不清空原来的家园。每完成一章，下一封最早在对应的下一天开放；错过日期不会丢失内容。</p>';showLifePanel(type,'住下来的七天',body);return true}
 if(type==='neighbors'){let body='<p>大家按游戏里的时间生活。忙碌或下雨时会换地方；商店无人时仍可自助购买。</p>';
 for(const who of LIFE_PEOPLE){const s=residentSchedule(who),n=RESIDENTS[who],events=availableFriendScenes(who),dish={rabbit:'salad',bear:'bread',turtle:'soup'}[who];body+=`<article class="neighbor-card"><div>${assetPortrait('people',PEOPLEFRAMES,LIFE_PEOPLE.indexOf(who),80)}</div><div><h3>${n.name}<span>好感 ${state.travel.relations[who]}</span></h3><p>${REGION_NAMES[s.region]} · ${s.activity}</p><small>喜欢 ${CROPS[n.favorite].name} / ${RECIPES[dish].name}</small>${lifeButton('find',who,'去找'+n.name)}${events.length?'<small class="new-story">有新的心事想告诉你</small>':''}</div></article>`}
 body+='<h3>坐一会儿，等风慢下来</h3><p>只推进今天的时间，不消耗体力。睡觉才会进入下一天。</p>'+lifeButton('wait','30','歇 30 分钟',state.minute>=1320)+lifeButton('wait','120','歇 2 小时',state.minute>=1320);showLifePanel(type,'邻居现在在哪里',body);return true}
 if(type.startsWith('resident:')){const who=type.split(':')[1],n=RESIDENTS[who];if(!n)return false;const s=residentSchedule(who),near=nearResident(who),events=availableFriendScenes(who),dish={rabbit:'salad',bear:'bread',turtle:'soup'}[who];let body=`<div class="neighbor-portrait">${assetPortrait('people',PEOPLEFRAMES,LIFE_PEOPLE.indexOf(who),120)}<div><small>${REGION_NAMES[s.region]} · ${s.activity}</small><p>${residentGreeting(who)}</p></div></div><div class="row"><span>熟悉程度</span><b>${state.travel.relations[who]}/100</b></div>`;
 if(!near)body+='<p>TA 已经去了别处，走近后再聊吧。</p>'+lifeButton('find',who,'去找'+n.name);
 body+=`<button data-travel="talk" data-key="${who}" ${!near||state.travel.talkDays[who]===state.day?'disabled':''}>${state.travel.talkDays[who]===state.day?'今天已经聊过':'聊聊天 · +4'}</button><button data-travel="gift" data-key="${who}" ${!near||state.travel.giftDays[who]===state.day||!state.stock[n.favorite]?'disabled':''}>送${CROPS[n.favorite].name} · +10</button>`;
 body+=`<p class="small">喜欢的料理：${RECIPES[dish].name}（+12），其他料理 +7。作物与料理每天共送一份，TA 会记住你送的礼物。</p>`+Object.entries(RECIPES).filter(([k])=>state.village.dishes[k]>0).map(([k,r])=>lifeButton('share',who+':'+k,'分享'+r.name,!near||state.travel.giftDays[who]===state.day)).join('');
 if(events.length)body+='<h3>想告诉你的一件事</h3>'+events.map(([k,e])=>lifeButton('friend',k,e.title,!near)).join('');
 const read=state.life.events.filter(k=>FRIEND_SCENES[k].who===who);if(read.length)body+='<h3>一起记得的事</h3>'+read.map(k=>lifeButton('friend',k,'重读 · '+FRIEND_SCENES[k].title)).join('');
 showLifePanel(type,n.name,body);return true}
 return false;
}
function openLifeScene(kind,id){let scene;if(kind==='chapter'){const n=Number(id);if(!int(n,0,6)||n>state.life.chapter||n===state.life.chapter&&!chapterAvailable())return;scene=LIFE_CHAPTERS[n];lifeScene={kind,id:n,page:0,replay:state.life.seen.includes(n),scene}}
 else if(kind==='friend'){scene=FRIEND_SCENES[id];if(!scene||!state.life.events.includes(id)&&(!nearResident(scene.who)||state.travel.relations[scene.who]<scene.level||id.endsWith('2')&&!state.life.events.includes(scene.who+'1')))return;lifeScene={kind,id,page:0,replay:state.life.events.includes(id),scene}}
 else {if(state.life.chapter!==7)return;const r=RECIPES[state.life.partyDish];scene={title:'今晚，不用一个人吃饭',subtitle:state.life.partyPlace==='cottage'?'雨声落在窗外':'庭院灯下',who:'bear',pages:[['兔兔','我带了洗好的果子。你那张长椅，收摊后借我坐一坐呀。'],['米米',r?'我先尝你的'+r.name+'。嗯，闻起来就知道你没有省那一步。下一次换我请大家。':'这次换你掌勺了。下一次换我请大家。'],['阿龟','杯子不太成套，不过都洗干净了。大家能坐在一处，就很好。'],['噜噜','有人抢着添汤，有人讲一件没什么大不了的小事。我忽然不想收拾得太快，想把这顿饭留得久一点。']]};lifeScene={kind:'album',id:'supper',page:0,replay:true,scene}}renderLifeScene()}
function renderLifeScene(){const a=lifeScene;if(!a)return;const p=a.scene.pages[a.page],last=a.page===a.scene.pages.length-1;const who=Object.keys(RESIDENTS).find(k=>RESIDENTS[k].name===p[0]);let body=`<div class="story-chapter">${a.scene.subtitle||'邻居的心事'}<span>${a.page+1}/${a.scene.pages.length}</span></div><div class="life-dialogue">${assetPortrait(who?'people':'hero',who?PEOPLEFRAMES:HERO,who?LIFE_PEOPLE.indexOf(who):0,130)}<div><b>${p[0]}</b><p>${p[1]}</p></div></div><div class="story-actions">${a.page?lifeButton('scene-back','','上一段'):''}`;
 if(!last)body+=lifeButton('scene-next','','继续 →');else if(a.replay)body+=lifeButton('scene-close','','收好这段回忆');else body+=a.scene.choices.map((c,i)=>lifeButton('scene-choice',i?'practical':'gentle',c)).join('');body+='</div>';showLifePanel('life-scene',a.scene.title,body);$('modal-close').textContent='先收起来，稍后再读';}
function chooseLifeScene(choice){const a=lifeScene;if(!a||a.replay||a.page!==a.scene.pages.length-1||!['gentle','practical'].includes(choice))return;
 if(a.kind==='chapter'){if(a.id!==state.life.chapter||state.life.seen.includes(a.id))return;state.life.seen.push(a.id);state.life.choices[a.id]=choice;save();hud();lifePanel('life');$('panel-message').textContent='记下了。事情可以按自己的节奏慢慢做。'}
 else if(a.kind==='friend'){if(state.life.events.includes(a.id))return;friendReward(a.id,choice);hud();lifePanel('resident:'+a.scene.who);$('panel-message').textContent=a.scene.answers[choice==='gentle'?0:1]+' '+a.scene.reward}lifeScene=null;
}
function lifeGoal(){if(partyActive())return {title:'今晚，邻居都来了',detail:'走近大家聊聊天，看看他们对这顿晚饭有什么话想说。下次也一起吃饭吧。',target:null,tool:null,menu:'neighbors'};const l=state.life,n=l.chapter;if(n===7||state.energy<4||state.minute>=1300)return null;const c=LIFE_CHAPTERS[n];if(!chapterAvailable())return null;
 const make=(detail,target=null,tool=null,menu='life')=>({title:`第 ${n+1} 封便条 · ${c.title}`,detail,target,tool,menu});
 if(!l.seen.includes(n))return make('邻居留下了一张新便条。点「开始这一步」读一读，再决定今天先做什么。');
 if(chapterReady())return make(n===6?'晚饭准备好了。点「开始这一步」，挑一道料理邀请大家。':'今天的小事做完了。点「开始这一步」，把它写进手记。');
 let region='home',target=null,detail='',tool=null;
 if(n===0){if(!l.counts.home){target=props[0];detail='先走进小屋，认一认床、柜子和工作台。'}else{const i=state.plots.findIndex(p=>p.crop&&!p.wet&&!ripe(p));tool=l.counts.sown?'water':'seed';target=beds[tool==='water'?Math.max(0,i):Math.max(0,state.plots.findIndex(p=>!p.crop))];detail=tool==='seed'?'去院子种下一颗种子。不用一次把整片田都忙完。':'给种下的田浇一点水。雨天已经湿润的田也算。'}}
 if(n===1){const who=LIFE_PEOPLE.find(k=>!l.met.includes(k)),s=residentSchedule(who);region=s.region;target={x:s.x,y:s.y,target:{x:s.x,y:s.y+34}};detail=`去和${RESIDENTS[who].name}聊聊天。现在在${REGION_NAMES[region]}，${s.activity}。`}
 if(n===2){region=l.counts.wood<3?'forest':'cottage';target=l.counts.wood<3?(state.region==='forest'?regionalProps().find(o=>o.type==='gather'&&visibleRegional(o)):null):{x:1090,y:475,target:{x:1090,y:513}};detail=l.counts.wood<3?`去树林收集干木材：${Math.min(3,l.counts.wood)}/3。`:'去小屋右侧工作台看看图纸，也可点下方「家园建设」。'}
 if(n===3){if(l.counts.harvested<2){const i=state.plots.findIndex(ripe);target=i<0?props[0]:beds[i];tool=i<0?null:'harvest';detail=i<0?'照顾好田地再回小屋过夜，等收成成熟。胡萝卜需要三个生长夜晚。':'收起至少两份成熟作物，留一颗胡萝卜给兔兔。'}else{const s=residentSchedule('rabbit');region=s.region;target={x:s.x,y:s.y,target:{x:s.x,y:s.y+34}};detail='带一颗胡萝卜去找兔兔，在聊天面板里送给她。'}}
 if(n===4){region='kitchen';target={x:1070,y:450,target:{x:1070,y:488}};detail='到料理铺右上角灶台，打开食谱，做一道料理。便条奖励的小麦可以做面包。'}
 if(n===5){region='cottage';target={x:1090,y:475,target:{x:1090,y:513}};detail='在工作台建一项喜欢的设施。长椅只要 3 木材和 50 金币，已有设施也算。'}
 if(n===6){region=state.rain?'cottage':'home';detail='留一份料理带回家，17:00 后打开「住下来的七天」邀请邻居。可以在里面等到傍晚。'}
 if(region!==state.region)return make(detail+' 可从「小岛地图」前往。',null,null,n===1||n===3&&l.counts.harvested>=2?'neighbors':'map');return make(detail,target,tool,target?null:'life');
}

// Hook successful actions only. Failure messages never advance chapters or play rewards.
const plotBeforeLife=workPlot;workPlot=function(i,action){const before={crop:state.plots[i]?.crop,wet:state.plots.filter(p=>p.wet).length,harvests:state.harvests},result=plotBeforeLife(i,action),p=state.plots[i];if(action==='seed'&&!before.crop&&p?.crop){recordLife('sown');if(p.wet)recordLife('watered');beginLifeAction('seed',beds[i],p.crop)}else if(action==='water'&&state.plots.filter(p=>p.wet).length>before.wet){recordLife('watered',state.plots.filter(p=>p.wet).length-before.wet);beginLifeAction('water',beds[i],p.crop)}else if(action==='harvest'&&state.harvests>before.harvests){recordLife('harvested',state.harvests-before.harvests);beginLifeAction('harvest',beds[i],before.crop)}return result};
const villageBeforeLife=villageAction;villageAction=function(action,key){const before=state.village.cooked,result=villageBeforeLife(action,key);if(state.village.cooked>before){recordLife('cooked');beginLifeAction('cook',{x:1070,y:450},key);save();hud()}return result};
const travelBeforeLife=travelAction;travelAction=function(action,key){if((action==='talk'||action==='gift')&&!nearResident(key))return '先走到这位邻居身边吧。「邻居在哪」可以查看位置。';const oldDay=state.travel[action==='talk'?'talkDays':'giftDays']?.[key],wood=state.travel.wood;let result=travelBeforeLife(action,key);if(action==='gather'&&state.travel.wood>wood)recordLife('wood',state.travel.wood-wood);if(action==='talk'&&oldDay!==state.day&&state.travel.talkDays[key]===state.day){if(!state.life.met.includes(key))state.life.met.push(key);result=RESIDENTS[key].name+'：'+residentGreeting(key);if(availableFriendScenes(key).length)result+=' 有一件心事，想单独和你说。'}if(action==='gift'&&oldDay!==state.day&&state.travel.giftDays[key]===state.day){state.life.memories[key]={type:'crop',key:RESIDENTS[key].favorite,day:state.day};if(key==='rabbit')state.life.giftCarrot=true;}save();hud();return result};
const panelsBeforeLife=panel;panel=function(type){stopWalking();if(!lifePanel(type))panelsBeforeLife(type);$('modal-title').focus({preventScroll:true});$('modal-title').parentElement?.scrollTo(0,0);if(type==='construction'){recordLife('plans');save();hud()}};
const goalsBeforeLife=nextGoal;nextGoal=function(){return lifeGoal()||goalsBeforeLife()};
const regionsBeforeLife=regionalProps;regionalProps=function(){return [...regionsBeforeLife().filter(o=>o.type!=='resident'),...scheduledResidents()]};
const homeBeforeLife=homeObjects;homeObjects=function(){return [...homeBeforeLife(),...scheduledResidents(),...(partyActive()&&state.life.partyPlace==='home'?[{type:'dining',interior:4,x:1050,y:1410,w:260,h:170,hit:{x:980,y:1370,w:140,h:35},target:{x:1050,y:1460}}]:[])]};
const recipeBeforeLife=recipeUnlocked;recipeUnlocked=function(r){return r.friend?state.life.events.includes(r.friend):recipeBeforeLife(r)};
const lifeBodyBefore=$('modal-body').onclick;$('modal-body').onclick=async e=>{const b=e.target.closest('button[data-life]');if(!b){if(lifeActionActive()&&e.target.closest('button[data-village="cook"]'))return;const before=state.village.cooked;lifeBodyBefore(e);if(state.village.cooked>before){dismiss();toast('噜噜正在认真做菜…')}return}if(b.disabled)return;const a=b.dataset.life,k=b.dataset.key;let message='';
 if(a==='chapter'||a==='friend'){openLifeScene(a,k);return}if(a==='album'){openLifeScene('album','supper');return}if(a==='scene-back'){lifeScene.page=Math.max(0,lifeScene.page-1);renderLifeScene();return}if(a==='scene-next'){lifeScene.page=Math.min(lifeScene.scene.pages.length-1,lifeScene.page+1);renderLifeScene();return}if(a==='scene-choice'){chooseLifeScene(k);return}if(a==='scene-close'){const who=lifeScene?.scene.who,kind=lifeScene?.kind;lifeScene=null;panel(kind==='friend'?'resident:'+who:'life');return}
 if(a==='finish'){message=finishChapter();panel('life')}
 if(a==='find'){const s=residentSchedule(k);if(state.region===s.region){dismiss();walkTo(s.x,s.y)}else goRegion(s.region);toast(RESIDENTS[k].name+'在'+REGION_NAMES[s.region]+'，'+s.activity+'。');return}
 if(a==='wait'){const n=k==='evening'?Math.max(0,1020-state.minute):['30','120'].includes(k)?Number(k):0;state.minute=Math.min(1320,state.minute+n);save();hud();panel($('modal').dataset.panel);message=state.minute>=1320?'夜深了，回床边睡到明天吧。':'歇了一会儿，邻居们也各自忙起来了。'}
 if(a==='share'){const [who,dish]=k.split(':');message=shareDish(who,dish);panel('resident:'+who)}
 if(a==='supper'){b.disabled=true;try{await Promise.all([...regionAssets(state.rain?'cottage':'home'),'furniture'].map(loadArt));message=startSupper(k);if(state.life.chapter===7){openLifeScene('album','supper');toast(message);return}}catch{message='晚饭场景还没加载好，请检查网络再试；料理保留在背包里。'}b.disabled=false}
 $('panel-message').textContent=message;
};
